"""Low-overhead AES-GCM implementation backed directly by OpenSSL EVP."""
try:
    from _fastaes import enc as _encrypt
except ImportError:  # portable fallback when the optional extension is unavailable
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM

    def _encrypt(key, nonce, plaintext, associated_data):
        result = AESGCM(key).encrypt(nonce, plaintext, associated_data)
        return {"ciphertext": result[:-16], "tag": result[-16:]}


class Solver:
    def solve(self, problem, **kwargs):
        return _encrypt(
            problem["key"],
            problem["nonce"],
            problem["plaintext"],
            problem["associated_data"],
        )
